ct_hex = "7f33a035c6390508cee1d0277f4712bf01a01a46677233f16387fae072d07bdee4f535b0bd66efa4f2475dc8515696cbc4bc2280c20c93726212695d770b0a8295e2bacbd6b59487b329cc36a5516567b948fed368bf02c50a39e6549312dc6badfef84d4e30494e9ef0a47bd97305639c875b16306fcd91146d3d126c1ea476"
ct = bytes.fromhex(ct_hex)

p_leak = '151441473357136152985216980397525591305875094288738820699069271674022167902643'
q_leak = '15624342005774166525024608067426557093567392652723175301615422384508274269305'

def reconstruct(p_len, q_len):
    """
    Reconstruct p and q digit by digit from LSD upward.
    For each position k, at most one of p_k, q_k is unknown.

    k=0: p_0 * q_0 ≡ n (mod 10)
    k>=1: p_k * (q_low % 10) + q_k * (p_low % 10) ≡ ((n - p_low*q_low) // 10^k) (mod 10)
    """
    # Map leaked digits to right-side positions
    p_known = {}
    for idx, ch in enumerate(p_leak):
        left_pos = idx * 2          # original left position
        right_pos = p_len - 1 - left_pos
        if 0 <= right_pos < p_len:
            p_known[right_pos] = int(ch)

    q_known = {}
    for idx, ch in enumerate(q_leak):
        left_pos = idx * 2 + 1      # original left position
        right_pos = q_len - 1 - left_pos
        if 0 <= right_pos < q_len:
            q_known[right_pos] = int(ch)

    # Check that no position has both unknown
    max_len = max(p_len, q_len)
    for k in range(max_len):
        if k not in p_known and k not in q_known:
            # Special case: if k >= both lengths, one is 0
            if k >= p_len:
                p_known[k] = 0
            elif k >= q_len:
                q_known[k] = 0
            else:
                return None  # both unknown - can't solve

    p_low = 0  # p mod 10^k
    q_low = 0  # q mod 10^k

    for k in range(max_len):
        if k == 0:
            # p_0 * q_0 ≡ n (mod 10)
            if 0 in p_known:
                p0 = p_known[0]
                # Solve for q0
                found = False
                for q0 in range(10):
                    if (p0 * q0) % 10 == n % 10:
                        found = True
                        break
                if not found:
                    return None
                if 0 in q_known and q_known[0] != q0:
                    return None
                q_known[0] = q0
            else:
                q0 = q_known[0]
                found = False
                for p0 in range(10):
                    if (p0 * q0) % 10 == n % 10:
                        found = True
                        break
                if not found:
                    return None
                p_known[0] = p0

            p_low = p0
            q_low = q0
        else:
            ten_k = 10 ** k
            # S_k = (n - p_low * q_low) // 10^k
            diff = n - p_low * q_low
            if diff % ten_k != 0:
                return None  # should be divisible
            S_k = diff // ten_k
            target = S_k % 10

            p0_digit = p_low % 10
            q0_digit = q_low % 10

            if k in p_known:
                p_k = p_known[k]
                # p_k * q0_digit + q_k * p0_digit ≡ target (mod 10)
                if p0_digit % 2 == 0 or p0_digit == 5:
                    # Try all possibilities
                    found = False
                    for q_k in range(10):
                        if (p_k * q0_digit + q_k * p0_digit) % 10 == target:
                            found = True
                            break
                    if not found:
                        return None
                else:
                    inv = pow(p0_digit, -1, 10)
                    q_k = ((target - p_k * q0_digit) * inv) % 10

                if k in q_known and q_known[k] != q_k:
                    return None
                q_known[k] = q_k
            else:
                q_k = q_known[k]
                if q0_digit % 2 == 0 or q0_digit == 5:
                    found = False
                    for p_k in range(10):
                        if (p_k * q0_digit + q_k * p0_digit) % 10 == target:
                            found = True
                            break
                    if not found:
                        return None
                else:
                    inv = pow(q0_digit, -1, 10)
                    p_k = ((target - q_k * p0_digit) * inv) % 10

                if k in p_known and p_known[k] != p_k:
                    return None
                p_known[k] = p_k

            p_low = p_k * ten_k + p_low
            q_low = q_k * ten_k + q_low

    # Verify
    if p_low * q_low != n:
        return None

    return p_low, q_low


# Try all plausible length combinations
for p_len in [155, 156]:
    for q_len in [154, 155]:
        result = reconstruct(p_len, q_len)
        if result:
            p, q = result
            print(f"SUCCESS! p_len={p_len}, q_len={q_len}")
            print(f"Verify p*q == n: {p * q == n}")

            # Decrypt
            phi = (p - 1) * (q - 1)
            e = 65537
            d = pow(e, -1, phi)

            key = RSA.construct((n, e, d, p, q))
            cipher = PKCS1_OAEP.new(key)
            flag = cipher.decrypt(ct)
            print(f"FLAG: {flag.decode()}")
            break
    else:
        continue
    break
